{"path":"/Users/philosopher/active/autopipe/autopipe/dashboard/frontend/src/pages/runs/RunCompare.tsx","content":"import { useEffect, useState } from 'react'
import { useSearchParams, useNavigate, Link } from 'react-router-dom'
import { useQuery } from '@tanstack/react-query'
import {
  ArrowLeft,
  ArrowRight,
  Check,
  ChevronDown,
  ChevronUp,
  Clock,
  GitBranch,
  GitCompare,
  Trophy,
  X,
} from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle, Button, Badge, Skeleton } from '@/components/ui'
import { runsApi, type MultiRunCompareResponse, type RunSummaryForComparison } from '@/api/endpoints/runs'
import { formatDistanceToNow } from '@/utils/helpers'

function formatDuration(seconds: number | null): string {
  if (!seconds) return 'N/A'
  if (seconds < 60) return `${Math.round(seconds)}s`
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ${Math.round(seconds % 60)}s`
  return `${Math.floor(seconds / 3600)}h ${Math.floor((seconds % 3600) / 60)}m`
}

function formatValue(value: unknown): string {
  if (value === null || value === undefined) return '-'
  if (typeof value === 'number') {
    if (Math.abs(value) >= 1000) return value.toFixed(0)
    if (Math.abs(value) >= 1) return value.toFixed(2)
    return value.toFixed(4)
  }
  if (typeof value === 'boolean') return value ? 'true' : 'false'
  return String(value)
}

function formatDelta(delta: number | null): { text: string; isPositive: boolean; isNegative: boolean } {
  if (delta === null || delta === undefined) return { text: '-', isPositive: false, isNegative: false }
  if (!isFinite(delta)) return { text: delta > 0 ? '+∞%' : '-∞%', isPositive: delta > 0, isNegative: delta < 0 }
  const sign = delta > 0 ? '+' : ''
  return {
    text: `${sign}${delta.toFixed(1)}%`,
    isPositive: delta > 0,
    isNegative: delta < 0,
  }
}

function StatusBadge({ status }: { status: string }) {
  const variants: Record<string, { variant: 'default' | 'secondary' | 'destructive' | 'outline' | null | undefined; className: string }> = {
    success: { variant: 'default', className: 'bg-green-500 hover:bg-green-600 text-white' },
    failed: { variant: 'destructive', className: '' },
    running: { variant: 'default', className: 'bg-blue-500 hover:bg-blue-600 text-white' },
    pending: { variant: 'secondary', className: '' },
    cancelled: { variant: 'outline', className: '' },
  }
  const variant = variants[status] || { variant: 'secondary', className: '' }
  return (
    <Badge variant={variant.variant} className={variant.className}>
      {status}
    </Badge>
  )
}

export function RunCompare() {
  const [searchParams, setSearchParams] = useSearchParams()
  const navigate = useNavigate()
  const [expandedParams, setExpandedParams] = useState(false)
  const [selectedRuns, setSelectedRuns] = useState<string[]>([])

  const runIds = searchParams.get('ids')?.split(',').filter(Boolean) || []

  const { data, isLoading, error } = useQuery<MultiRunCompareResponse>({
    queryKey: ['runs', 'compare', runIds.join(',')],
    queryFn: () => runsApi.compareMultiple(runIds),
    enabled: runIds.length >= 2,
  })

  // Initialize selected runs when data loads
  useEffect(() => {
    if (data?.runs && selectedRuns.length === 0) {
      setSelectedRuns(data.runs.map(r => r.id))
    }
  }, [data, selectedRuns.length])

  const handleRemoveRun = (runId: string) => {
    const newIds = runIds.filter(id => id !== runId)
    if (newIds.length < 2) {
      navigate('/runs')
    } else {
      setSearchParams({ ids: newIds.join(',') })
    }
  }

  const handleAddRun = () => {
    navigate('/runs')
  }

  if (runIds.length < 2) {
    return (
      <div className="p-8">
        <Card>
          <CardContent className="py-12">
            <div className="text-center">
              <GitCompare className="w-12 h-12 mx-auto mb-4 text-muted-foreground" />
              <h2 className="text-lg font-semibold mb-2">Select Runs to Compare</h2>
              <p className="text-muted-foreground mb-4">Select at least 2 runs from the runs list to compare them.</p>
              <Button onClick={handleAddRun}>
                <ArrowLeft className="w-4 h-4 mr-2" />
                Go to Run List
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    )
  }

  if (isLoading) {
    return (
      <div className="p-6">
        <div className="flex items-center gap-2 mb-6">
          <Skeleton className="h-9 w-32" />
          <Skeleton className="h-9 w-48" />
        </div>
        <div className="grid gap-4">
          {runIds.map((_, i) => (
            <Skeleton key={i} className="h-24" />
          ))}
        </div>
      </div>
    )
  }

  if (error || !data) {
    return (
      <div className="p-8">
        <Card>
          <CardContent className="py-12">
            <div className="text-center">
              <X className="w-12 h-12 mx-auto mb-4 text-destructive" />
              <h2 className="text-lg font-semibold mb-2">Failed to Load Comparison</h2>
              <p className="text-muted-foreground mb-4">{(error as Error)?.message || 'Unknown error'}</p>
              <Button onClick={() => window.location.reload()}>
                Retry
              </Button>
            </div>
          </CardContent>
        </Card>
      </div>
    )
  }

  const { runs, parameters, metrics, diff_summary } = data

  // Filter to selected runs
  const visibleRuns = runs.filter(r => selectedRuns.includes(r.id))

  return (
    <div className="p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <Link to="/runs">
              <Button variant="ghost" size="sm">
                <ArrowLeft className="w-4 h-4 mr-1" />
                Runs
              </Button>
            </Link>
            <span className="text-muted-foreground">/</span>
            <h1 className="text-xl font-semibold">Compare Runs</h1>
          </div>
          <p className="text-sm text-muted-foreground">
            {visibleRuns.length} runs selected • {diff_summary.total_params} parameters • {diff_summary.total_metrics} metrics
          </p>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" onClick={handleAddRun}>
            <GitBranch className="w-4 h-4 mr-2" />
            Add Run
          </Button>
        </div>
      </div>

      {/* Run Headers */}
      <div className="grid gap-4" style={{ gridTemplateColumns: `200px repeat(${visibleRuns.length}, minmax(180px, 1fr))` }}>
        <div className="font-medium text-muted-foreground p-2">Run</div>
        {visibleRuns.map((run) => (
          <Card key={run.id} className="relative">
            <Button
              variant="ghost"
              size="sm"
              className="absolute top-1 right-1 h-6 w-6 p-0"
              onClick={() => handleRemoveRun(run.id)}
            >
              <X className="w-3 h-3" />
            </Button>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium truncate pr-6">
                {run.pipeline_name || run.pipeline_id}
              </CardTitle>
            </CardHeader>
            <CardContent className="pt-0">
              <div className="flex items-center gap-2 mb-1">
                <StatusBadge status={run.status} />
                <span className="text-xs text-muted-foreground">Run {run.run_number}</span>
              </div>
              <div className="text-xs text-muted-foreground">
                {formatDuration(run.duration_seconds || null)} • {formatDistanceToNow(run.created_at)}
              </div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Metrics Section */}
      {metrics.length > 0 && (
        <div>
          <h2 className="text-lg font-semibold mb-3 flex items-center gap-2">
            <Trophy className="w-5 h-5" />
            Metrics
          </h2>
          <div className="overflow-x-auto">
            <table className="w-full border-collapse">
              <tbody>
                {/* Best metric per row indicator */}
                {metrics.map((metric) => {
                  const isHighlighted = diff_summary.best_metric_per_key[metric.name] === undefined ? false : 
                    selectedRuns.includes(diff_summary.best_metric_per_key[metric.name])
                  return (
                    <tr key={metric.name} className="border-t hover:bg-muted/50">
                      <td className="p-3 w-[200px] font-medium">
                        <div className="flex items-center gap-2">
                          {metric.name}
                          {isHighlighted && (
                            <Trophy className="w-3 h-3 text-amber-500" />
                          )}
                        </div>
                        <div className="text-xs text-muted-foreground">
                          {metric.higher_is_better ? 'higher is better' : 'lower is better'}
                        </div>
                      </td>
                      {visibleRuns.map((run) => {
                        const value = metric.values[run.id]
                        const isBest = metric.best_run_id === run.id
                        const delta = formatDelta(value?.delta_from_baseline || null)
                        return (
                          <td key={run.id} className="p-3 min-w-[180px]">
                            <div className="flex items-baseline gap-2">
                              <span className={`text-lg font-semibold ${isBest ? 'text-green-600' : ''}`}>
                                {formatValue(value?.value)}
                              </span>
                              {value?.delta_from_baseline !== null && run.id !== runs[0]?.id && (
                                <span className={`text-sm ${delta.isPositive ? 'text-green-600' : delta.isNegative ? 'text-red-600' : 'text-muted-foreground'}`}>
                                  {delta.isPositive ? <ArrowUp className="w-3 h-3 inline" /> : delta.isNegative ? <ArrowDown className="w-3 h-3 inline" /> : null}
                                  {delta.text}
                                </span>
                              )}
                            </div>
                          </td>
                        )
                      })}
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Parameters Section */}
      {parameters.length > 0 && (
        <div>
          <button
            onClick={() => setExpandedParams(!expandedParams)}
            className="flex items-center gap-2 mb-3 hover:opacity-70"
          >
            {expandedParams ? <ChevronUp className="w-5 h-5" /> : <ChevronDown className="w-5 h-5" />}
            <h2 className="text-lg font-semibold">
              Parameters
              <span className="ml-2 text-sm text-muted-foreground font-normal">
                ({diff_summary.different_params} different of {diff_summary.total_params})
              </span>
            </h2>
          </button>

          {(expandedParams || diff_summary.different_params <= 10) && (
            <div className="overflow-x-auto">
              <table className="w-full border-collapse">
                <tbody>
                  {(expandedParams ? parameters : parameters.filter(p => p.is_different)).map((param) => (
                    <tr key={param.name} className={`border-t hover:bg-muted/50 ${param.is_different ? 'bg-amber-50/50' : ''}`}>
                      <td className="p-3 w-[200px] font-medium">{param.name}</td>
                      {visibleRuns.map((run) => (
                        <td key={run.id} className="p-3 min-w-[180px] font-mono text-sm">
                          {formatValue(param.values[run.id])}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {!expandedParams && diff_summary.different_params > 10 && (
            <Button variant="ghost" onClick={() => setExpandedParams(true)}>
              Show {parameters.length - diff_summary.different_params} identical parameters
            </Button>
          )}
        </div>
      )}

      {/* Empty State */}
      {parameters.length === 0 && metrics.length === 0 && (
        <Card>
          <CardContent className="py-12 text-center">
            <Clock className="w-12 h-12 mx-auto mb-4 text-muted-foreground" />
            <h2 className="text-lg font-semibold mb-2">No Data Available</h2>
            <p className="text-muted-foreground">These runs don't have any parameters or metrics to compare.</p>
          </CardContent>
        </Card>
      )}
    </div>
  )
}
"}

